@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  /* the box keeps its padding; the toggle's 24 px target overhangs it by 4 px */
  .nz-password-input-toggle {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    inline-size: var(--nz-space-6);
    block-size: var(--nz-space-6);
    margin-inline-end: calc(-1 * var(--nz-space-1));
    padding: 0;
    border: 0;
    border-radius: var(--nz-radius-sm);
    background: transparent;
    color: var(--nz-password-input-toggle-fg, var(--nz-icon-secondary));
    font-size: var(--nz-size-icon-sm);
    cursor: pointer;
    transition:
      background-color var(--nz-duration-fast) var(--nz-easing-standard),
      color var(--nz-duration-fast) var(--nz-easing-standard);

    @media (hover: hover) {
      &:hover:not(:disabled) {
        background: var(--nz-bg-hover);
        color: var(--nz-icon-primary);
      }
    }

    &:active:not(:disabled) {
      background: var(--nz-bg-pressed);
    }

    &:disabled {
      color: var(--nz-text-disabled);
      cursor: not-allowed;
    }
  }

  .nz-password-input-icon {
    display: inline-flex;
  }

  /* one outline at a time: the toggle's own, not the box's around it as well */
  .nz-password-input:has(> .nz-password-input-toggle:focus) {
    outline: none;
    box-shadow: none;
  }

  @media (forced-colors: active) {
    .nz-password-input-toggle {
      color: ButtonText;
    }

    .nz-password-input-toggle:disabled {
      color: GrayText;
    }
  }
}
